import{_ as o,o as a,c as t,a2 as n}from"./chunks/framework.Do1fvF3d.js";const p=JSON.parse('{"title":"Frequently asked questions","description":"","frontmatter":{},"headers":[],"relativePath":"en/guia/preguntas-frecuentes.md","filePath":"en/guia/preguntas-frecuentes.md","lastUpdated":null}'),r={name:"en/guia/preguntas-frecuentes.md"};function s(i,e,h,l,d,u){return a(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="frequently-asked-questions" tabindex="-1">Frequently asked questions <a class="header-anchor" href="#frequently-asked-questions" aria-label="Permalink to &quot;Frequently asked questions&quot;">​</a></h1><h2 id="is-it-free" tabindex="-1">Is it free? <a class="header-anchor" href="#is-it-free" aria-label="Permalink to &quot;Is it free?&quot;">​</a></h2><p>Yes. It is an open-source project.</p><h2 id="do-i-have-to-upload-my-contacts" tabindex="-1">Do I have to upload my contacts? <a class="header-anchor" href="#do-i-have-to-upload-my-contacts" aria-label="Permalink to &quot;Do I have to upload my contacts?&quot;">​</a></h2><p>No. Contributing your address book is optional and the app works the same without it. Your contacts are read on your phone to show people you know in green, and that sends nothing.</p><h2 id="can-you-see-who-i-call-or-who-calls-me" tabindex="-1">Can you see who I call or who calls me? <a class="header-anchor" href="#can-you-see-who-i-call-or-who-calls-me" aria-label="Permalink to &quot;Can you see who I call or who calls me?&quot;">​</a></h2><p>We do not store who looked up which number. Call history stays on your phone.</p><h2 id="why-isn-t-the-name-i-saved-shown" tabindex="-1">Why isn&#39;t the name I saved shown? <a class="header-anchor" href="#why-isn-t-the-name-i-saved-shown" aria-label="Permalink to &quot;Why isn&#39;t the name I saved shown?&quot;">​</a></h2><p>A name is only shown to others if at least 3 different people saved it the same way. That way, something only you wrote (for example &quot;Juan from work&quot;) is never shown to anyone else. On your own phone you always see your saved name.</p><h2 id="does-it-work-on-iphone" tabindex="-1">Does it work on iPhone? <a class="header-anchor" href="#does-it-work-on-iphone" aria-label="Permalink to &quot;Does it work on iPhone?&quot;">​</a></h2><p>Not yet. The first version is for Android 10 or later.</p><h2 id="what-if-there-is-no-internet" tabindex="-1">What if there is no internet? <a class="header-anchor" href="#what-if-there-is-no-internet" aria-label="Permalink to &quot;What if there is no internet?&quot;">​</a></h2><p>The call rings normally. Your contacts show in green and everyone else in orange, with the notice &quot;No connection&quot;.</p><h2 id="how-do-i-delete-everything" tabindex="-1">How do I delete everything? <a class="header-anchor" href="#how-do-i-delete-everything" aria-label="Permalink to &quot;How do I delete everything?&quot;">​</a></h2><p>In the app: <strong>Account → Delete my account</strong>. Your account, your reports and your contributions are deleted.</p>',15)])])}const y=o(r,[["render",s]]);export{p as __pageData,y as default};
